package dev.codesomething.profile;

import java.util.*;

/** Separate transfer questions; never return the key before submission. */
final class ReviewQuestions {
    record Question(String prompt,List<String> options,int correct,String explanation) {}
    private static Question q(String prompt,int answer,String explanation,String... options){return new Question(prompt,List.of(options),answer,explanation);}
    static Question get(String stage,int variant){
        boolean b=variant%2==1;
        return switch(stage){
            case "run-server" -> b?q("程序打印已启动，但请求使用了另一个端口。先检查什么？",2,"客户端目标端口必须与服务监听端口一致。","重命名JSON字段","删除数据库","请求地址与监听端口") :q("服务监听8093，客户端却访问8094。最直接的修复是什么？",1,"请求必须发送到实际监听的端口。","修改JSON类型","把请求端口改为8093","清空缓存表");
            case "fix-response" -> b?q("查询不存在的商品，哪个响应更符合资源查询约定？",0,"不存在的资源应明确返回404，避免以200冒充成功。","404及错误说明","200和任意旧商品","始终不响应") :q("库存字段inStock表达是否有货，哪个JSON值类型合适？",2,"JSON的true是布尔值，带引号会成为字符串。","\"true\"","\"1\"","true");
            case "transfer" -> b?q("任务接口迁移为收藏接口后，测试仍访问旧路由，应如何处理？",1,"迁移需要同步路由、字段、业务映射和对应测试。","删除所有测试","同步路由及测试断言","只改网页标题") :q("把任务接口改为书评接口，哪个检查能验证迁移？",0,"新业务应在新路由返回对应字段，旧测试不能替代迁移验证。","访问新路由并核对书评字段","只看进程仍在运行","只改类名");
            case "db-connect" -> b?q("连接成功后DATABASE()返回demo，课程表却在practice库。应先做什么？",0,"连接成功不代表选对数据库，应检查当前库与目标库。","切换到正确数据库再查表","删除JDK","把查询改成HTTP请求") :q("SELECT 1成功，但查询notes提示表不存在。最有帮助的下一项检查是？",1,"先核对当前库和表名，区分连接问题与对象定位问题。","重新安装浏览器","查询DATABASE()并核对表名","给所有字段加引号");
            case "db-model" -> b?q("希望每条收藏都有唯一编号，最合适的数据库约束是什么？",2,"主键保证每行有唯一且非空的标识。","任意字符串注释","只在网页显示编号","主键") :q("notes表主键id已有12，再插入id=12，应预期什么？",0,"主键不允许重复值，应修正编号或采用生成策略。","主键冲突","自动更新标题","清空整张表");
            case "sql-read" -> b?q("商品价格为8、20、30，WHERE price>=20会选哪些价格？",1,"大于等于包含边界20。","8和20","20和30","只有30") :q("书签4和9已归档，7未归档。WHERE archived=0返回哪个编号？",2,"条件只保留archived为0的行。","4和9","全部编号","7");
            case "sql-write" -> b?q("只想删除id=31的书评，DELETE语句必须带什么限制？",0,"WHERE id=31将删除范围限制到目标行。","WHERE id=31","ORDER BY title","不需要条件") :q("只改编号18的标题，UPDATE notes SET title='新标题'少了什么？",1,"没有WHERE会更新全部行，必须限制目标记录。","LIMIT用于连接数据库","WHERE id=18","返回JSON");
            case "sql-page" -> b?q("按created_at分页，多行时间相同，如何稳定顺序？",2,"增加唯一id作为并列时的排序依据。","去掉ORDER BY","每次随机排序","ORDER BY created_at,id") :q("每页4条，取第3页，零起始偏移应为多少？",0,"前两页共8条，所以OFFSET为8。","8","4","12");
            case "sql-transfer" -> b?q("将任务的completed改为收藏的pinned，哪些地方要一致？",1,"表结构、写入字段、查询和结果映射都需要遵循新模型。","只改网页文字","表结构、写入与查询映射","只改数据库密码") :q("把任务迁移为笔记，只改表名却继续读取completed，风险是什么？",2,"业务字段变化需要同步查询和映射，否则出错或返回错误含义。","没有任何风险","端口必然冲突","查询字段与新模型不一致");
            case "boot-start" -> b?q("Maven构建成功但访问端口错误，能据此断定业务实现错误吗？",0,"先核对启动日志与监听地址，构建与运行环境是不同检查。","先检查监听端口和启动日志","一定是SQL错误","必须删除源码") :q("Spring Boot进程启动后，哪种证据能确认健康接口可用？",1,"真实HTTP请求能验证路由、端口和响应，而非只看文件存在。","看见pom.xml","请求健康路由并核对响应","只看工程名称");
            case "boot-http" -> b?q("GET /notes/24中24用路径变量接收，应该核对什么？",2,"路径模板占位符与方法参数的绑定必须一致。","只核对数据库密码","只核对CSS类名","路由占位符与参数绑定") :q("POST接收JSON DTO，浏览器传入的数字字段要在哪里转换和校验？",0,"框架反序列化为DTO后再进行边界校验。","请求绑定的DTO及校验层","在网页标题中","把JSON当SQL直接执行");
            case "boot-layers" -> b?q("Controller直接拼SQL并实现所有业务，分层重构应如何安排？",1,"Controller接收请求，Service编排业务，Repository处理持久化。","复制到三个类即可","按请求、业务、数据访问职责拆分","把业务写入CSS") :q("Service依赖Repository，构造器注入的作用是什么？",2,"构造器使依赖显式，可替换实现并便于测试。","自动创建所有表","绕过所有测试","显式提供数据访问依赖");
            case "boot-jdbc" -> b?q("JDBC查询不到记录，映射前首先需要判断什么？",0,"先判断结果集是否有下一行，再读取列值。","结果集是否存在下一行","浏览器颜色","字符串长度必须为0") :q("用户标题中含单引号，如何安全写入数据库？",1,"参数绑定将输入作为值传递，避免字符串拼接改变SQL结构。","直接拼接SQL","PreparedStatement参数绑定","移除全部空格");
            case "a-read" -> b?q("查询单个任务不存在时，哪个行为更明确？",2,"明确404能与正常空列表或服务器故障区分。","返回任意第一条任务","一律返回500","按契约返回404") :q("列表为空时，哪种响应能表达正常查询结果？",0,"查询成功且没有记录可返回空集合。","200与空集合","500与堆栈","返回已删除任务");
            case "a-create" -> b?q("新增后客户端需要更新或删除这条记录，响应中哪个字段关键？",1,"持久化记录的真实id用于后续定位操作。","页面颜色","数据库生成的记录id","服务器安装路径") :q("新增任务成功后，怎样验证它确实被保存？",2,"使用返回的id再查询，验证持久化结果。","只看按钮变色","只看请求已发送","按返回id重新读取并核对内容");
            case "a-update-delete" -> b?q("修改任务返回成功，但数据库行数影响为0，首先检查什么？",0,"更新零行可能是目标不存在，应核对id并按契约处理。","目标id是否存在及不存在的响应","页面字号","把所有任务都更新") :q("删除编号52后，哪个验证有意义？",1,"检查目标不存在且其他记录未被误删。","只检查日志有delete字样","再次查52且核对其他记录保留","清空全部表");
            case "a-validation" -> b?q("标题长度超过约定上限，服务端应如何处理？",2,"按契约返回明确的客户端错误，避免无效数据入库。","静默截断且总返回成功","显示数据库密码","拒绝并说明字段原因") :q("前端已限制空标题，后端还需要校验吗？",0,"客户端可绕过，后端必须维护数据约束。","需要，API也可能被直接调用","不需要","仅部署后需要");
            case "a-pagination" -> b?q("筛选未完成任务时，total却统计全部任务，哪里不一致？",1,"总数查询与分页数据查询必须使用相同筛选。","端口号","计数和数据查询的筛选条件","主键名称") :q("每页5条取第2页，数据排序中有并列值，应怎样查？",2,"OFFSET为5且以唯一id稳定并列顺序。","随机取5条","OFFSET 10且无排序","固定排序并增加id，OFFSET 5");
            case "a-transfer" -> b?q("从任务迁移到书签，怎样证明自己理解了实现？",0,"陌生变更与数据流说明可补充复制代码无法提供的证据。","独立改动新需求并解释请求到数据库的数据流","只替换项目标题","删除测试使构建成功") :q("书签迁移提交包含源码，怎样让他人可靠复现？",1,"测试与运行说明应覆盖业务和环境准备，便于他人复现。","只提供截图","提供测试、建表与运行说明","只写一句已完成");
            case "b-login" -> b?q("密码已修改但旧会话仍有效，服务端怎样立即使它失效？",1,"服务端撤销会话摘要，后续请求无法认证。","只清空页面文字","删除或撤销服务端会话","只隐藏退出按钮"):q("浏览器刷新后内存令牌丢失，最合适的恢复是什么？",2,"身份必须重新通过受支持的登录流程确认。","把用户名当令牌","修改CSS","重新登录取得新会话");
            case "b-roles" -> b?q("管理员读取某计划时没有成员关系，应怎样处理？",0,"全局审计角色不等于计划成员权限。","按成员规则拒绝","自动成为负责人","根据前端按钮判断"):q("成员把任务id改为另一计划的编号，哪个检查最关键？",1,"对象归属必须与已授权计划同时匹配。","只核对请求是PUT","同时核对plan_id、task_id和用户权限","只检查数字格式");
            case "b-plans" -> b?q("创建计划成功但本人不能查看，可能漏了哪项原子写入？",2,"创建计划时应同时建立负责人本人的成员关系。","网页标题","密码摘要","memberships中的本人关系"):q("同一用户加入同一计划两次，什么约束防止重复关系？",0,"复合主键表达一对成员关系唯一。","(plan_id,user_id)复合主键","任务标题长度","日志级别");
            case "b-pagination" -> b?q("只查计划7的done任务，COUNT应包含什么条件？",1,"总数和页内数据必须使用同一范围。","所有计划所有任务","plan_id=7与status=done","只用LIMIT"):q("同一页每次编号顺序变化，分页查询缺什么？",2,"稳定且唯一的排序防止分页跳项。","随机排序","删掉权限检查","ORDER BY唯一id");
            case "b-transaction" -> b?q("事务方法内部捕获错误并返回成功，已插入的第一项可能怎样？",0,"异常未向事务边界传播可能导致部分写入被提交。","被提交，破坏整批原子性","一定自动回滚","只能丢失日志"):q("同一Service内部直接调用带@Transactional的方法，为何要小心？",1,"默认代理模式下自调用可能绕过事务代理。","必须改标题","可能绕过Spring事务代理","数据库不能有外键");
            case "b-errors-logs" -> b?q("错误正文requestId与响应头不同，会影响什么？",2,"同一请求需要一致编号才能关联日志。","SQL必然重复","角色自动改变","排错时难以关联同一请求"):q("哪个日志内容适合保留？",0,"请求编号、方法与状态有助定位且不泄露会话。","请求编号、方法、状态","完整Authorization令牌","明文登录密码");
            case "b-tests" -> b?q("删除成员校验后测试仍通过，下一步是什么？",1,"补上真实越权请求和具体状态断言。","发布即可","新增跨计划越权断言","删除全部测试"):q("测试只断言接口返回非空，能否验证事务回滚？",2,"回滚需比较失败前后的业务状态与审计状态。","能证明全部回滚","不用数据库","不能，须比较任务与审计状态");
            case "b-deploy" -> b?q("部署端口被另一个进程占用，应归入哪类？",0,"端口冲突是环境故障，应单独排查。","环境问题","必然不懂权限","自动算完成"):q("重启容器后仍需保留数据，数据库文件应放在哪里？",1,"持久数据卷独立于应用进程与临时文件。","应用内存","独立持久数据卷","浏览器缓存");
            default -> throw new IllegalArgumentException("Unknown review stage");
        };
    }
}
